package com.fakelegacy.catalog;

import java.time.LocalDateTime;
import java.util.List;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
public class ReservationExpiryJob {

    private final StockReservationRepository reservationRepository;
    private final StockController stockController;

    public ReservationExpiryJob(StockReservationRepository reservationRepository, StockController stockController) {
        this.reservationRepository = reservationRepository;
        this.stockController = stockController;
    }

    @Scheduled(fixedDelay = 60000, initialDelay = 60000)
    @Transactional
    public void releaseExpired() {
        List<StockReservation> expired = reservationRepository
                .findByStatusAndExpiresAtBefore(StockReservation.ACTIVE, LocalDateTime.now());
        for (StockReservation r : expired) {
            stockController.expire(r);
        }
    }
}
